INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mood', 'n.', '/muːd/', '心情;情绪', 'A few good jokes can quickly put you in a happy mood.', '几个好笑话能很快让你心情愉快。', 'Laugh Out Loud', 1, 0, 'senior', 'wordlist', 'elective1', 'U1', 'in a good mood', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'circus', 'n.', '/ˈsɜːkəs/', '马戏团', 'The clown first learned his funny tricks at a travelling circus.', '这个小丑最初在一个流动马戏团学会了他的滑稽把戏。', 'Laugh Out Loud', 2, 0, 'senior', 'wordlist', 'elective1', 'U1', 'at the circus', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'amusement', 'n.', '/əˈmjuːzmənt/', '娱乐;消遣;愉悦', 'The children watched the clown with great amusement.', '孩子们饶有兴致地看着小丑。', 'Laugh Out Loud', 3, 0, 'senior', 'wordlist', 'elective1', 'U1', 'with amusement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'amusement park', 'n.', '/əˈmjuːzmənt pɑːk/', '游乐场', 'You can often see clowns making people laugh at an amusement park.', '在游乐场你常能看到小丑逗人发笑。', 'Laugh Out Loud', 4, 0, 'senior', 'wordlist', 'elective1', 'U1', 'go to an amusement park', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'curly', 'adj.', '/ˈkɜːli/', '卷曲的', 'The clown put on a bright curly rainbow wig before his show.', '演出前小丑戴上了一顶鲜艳的卷曲彩虹假发。', 'Laugh Out Loud', 5, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a curly wig', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wig', 'n.', '/wɪɡ/', '假发', 'His funny wig and red nose made all the children laugh.', '他滑稽的假发和红鼻子把所有孩子都逗笑了。', 'Laugh Out Loud', 6, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a rainbow wig', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'badge', 'n.', '/bædʒ/', '徽章;名牌', 'His name badge read ''Doctor Laugh-Out-Loud''.', '他的名牌上写着''开怀大笑医生''。', 'Laugh Out Loud', 7, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a name badge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ankle', 'n.', '/ˈæŋk(ə)l/', '脚踝', 'The little girl had hurt her ankle and was crying in pain.', '小女孩扭伤了脚踝,正疼得直哭。', 'Laugh Out Loud', 8, 0, 'senior', 'wordlist', 'elective1', 'U1', 'hurt one''s ankle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'clown', 'n.', '/klaʊn/', '小丑', 'A clown doctor cheers up children who are ill in hospital.', '小丑医生为住院的患病儿童带去欢乐。', 'Laugh Out Loud', 9, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a clown doctor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'entertain', 'v.', '/ˌentəˈteɪn/', '使快乐;娱乐', 'Clown doctors entertain young patients with magic tricks and jokes.', '小丑医生用魔术和笑话给小患者带来欢乐。', 'Laugh Out Loud', 10, 0, 'senior', 'wordlist', 'elective1', 'U1', 'entertain the patients', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'health care', 'n.', '/ˈhelθ keə/', '医疗保健', 'Clown doctors work in hospitals and other health care places.', '小丑医生在医院和其他医疗保健场所工作。', 'Laugh Out Loud', 11, 0, 'senior', 'wordlist', 'elective1', 'U1', 'health care facilities', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cheer up', 'v.', '/tʃɪər ʌp/', '(使)高兴起来;(使)振作', 'We sing silly songs to cheer up the children on the ward.', '我们唱滑稽的歌来让病房里的孩子们高兴起来。', 'Laugh Out Loud', 12, 0, 'senior', 'wordlist', 'elective1', 'U1', 'cheer up a patient', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'do the trick', 'phr.', '/duː ðə trɪk/', '奏效;达到预期效果', 'A funny joke often does the trick when a child feels sad.', '当孩子难过时,一个好笑的笑话常常很奏效。', 'Laugh Out Loud', 13, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a joke does the trick', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'examine', 'v.', '/ɪɡˈzæmɪn/', '检查(身体)', 'While the doctor examined her ankle, the clown did a magic trick.', '医生检查她脚踝时,小丑变了个魔术。', 'Laugh Out Loud', 14, 0, 'senior', 'wordlist', 'elective1', 'U1', 'examine an injury', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advertisement', 'n.', '/ədˈvɜːtɪsmənt/', '广告', 'The hospital put out an advertisement for a part-time clown doctor.', '医院登了一则招聘兼职小丑医生的广告。', 'Laugh Out Loud', 15, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a job advertisement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'employer', 'n.', '/ɪmˈplɔɪə/', '雇主;雇用者', 'The Healthy Humour Foundation is the clown doctor''s employer.', '健康幽默基金会是这位小丑医生的雇主。', 'Laugh Out Loud', 16, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a kind employer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'essential', 'adj.', '/ɪˈsenʃ(ə)l/', '极其重要的;必不可少的', 'Humour has been an essential part of human life for thousands of years.', '幽默几千年来一直是人类生活必不可少的一部分。', 'Laugh Out Loud', 17, 0, 'senior', 'wordlist', 'elective1', 'U1', 'an essential part', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'impress', 'v.', '/ɪmˈpres/', '使钦佩;给……留下深刻印象', 'He told a clever joke that he hoped would impress his friends.', '他讲了个聪明的笑话,希望能让朋友们佩服。', 'Laugh Out Loud', 18, 0, 'senior', 'wordlist', 'elective1', 'U1', 'impress one''s friends', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'grin', 'v./n.', '/ɡrɪn/', '露齿而笑;咧嘴笑', 'She could not help but grin at his silly joke.', '听到他愚蠢的笑话,她忍不住咧嘴笑了。', 'Laugh Out Loud', 19, 0, 'senior', 'wordlist', 'elective1', 'U1', 'grin happily', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'deserve', 'v.', '/dɪˈzɜːv/', '应得;应受到', 'After such a hard day, the tired nurses deserve a good laugh.', '辛苦了一天,疲惫的护士们应该好好笑一场。', 'Laugh Out Loud', 20, 0, 'senior', 'wordlist', 'elective1', 'U1', 'deserve a laugh', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'long face', 'n.', '/lɒŋ feɪs/', '愁眉苦脸', 'Why the long face? Here is a joke to cheer you up.', '怎么愁眉苦脸的?给你讲个笑话开心一下。', 'Laugh Out Loud', 21, 0, 'senior', 'wordlist', 'elective1', 'U1', 'pull a long face', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'laughing stock', 'n.', '/ˈlɑːfɪŋ stɒk/', '笑柄;笑料', 'After he fell over, he became the laughing stock of the whole class.', '摔了一跤后,他成了全班的笑柄。', 'Laugh Out Loud', 22, 0, 'senior', 'wordlist', 'elective1', 'U1', 'become the laughing stock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'crack a smile', 'phr.', '/kræk ə smaɪl/', '笑了起来;露出笑容', 'Even the strict teacher began to crack a smile at the joke.', '连严厉的老师都被那个笑话逗得露出了笑容。', 'Laugh Out Loud', 23, 0, 'senior', 'wordlist', 'elective1', 'U1', 'finally crack a smile', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'practical joke', 'n.', '/ˌpræktɪk(ə)l ˈdʒəʊk/', '恶作剧', 'On April Fool''s Day, people love to play a practical joke on each other.', '愚人节那天,人们喜欢互相搞恶作剧。', 'Laugh Out Loud', 24, 0, 'senior', 'wordlist', 'elective1', 'U1', 'play a practical joke', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fame', 'n.', '/feɪm/', '名声;名誉', 'Mark Twain won fame for his witty remarks and funny stories.', '马克·吐温因风趣的言论和好笑的故事而成名。', 'Laugh Out Loud', 25, 0, 'senior', 'wordlist', 'elective1', 'U1', 'win fame', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'linguist', 'n.', '/ˈlɪŋɡwɪst/', '语言学家', 'Lin Yutang was a writer and linguist who loved humour.', '林语堂是一位热爱幽默的作家兼语言学家。', 'Laugh Out Loud', 26, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a famous linguist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'witty', 'adj.', '/ˈwɪti/', '说话风趣的;妙趣横生的', 'Twain was famous for his witty replies to ordinary people.', '吐温以对普通人妙趣横生的回答而闻名。', 'Laugh Out Loud', 27, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a witty reply', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'medieval', 'adj.', '/ˌmediˈiːv(ə)l/', '中世纪的;中古时期的', 'Even medieval writings are filled with clever jokes.', '甚至中世纪的著作里也充满了巧妙的笑话。', 'Laugh Out Loud', 28, 0, 'senior', 'wordlist', 'elective1', 'U1', 'medieval writings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'emotive', 'adj.', '/ɪˈməʊtɪv/', '使情绪激动的', 'Humour can throw new light on emotive or sensitive issues.', '幽默能为令人激动或敏感的话题带来新的视角。', 'Laugh Out Loud', 29, 0, 'senior', 'wordlist', 'elective1', 'U1', 'emotive issues', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mischievous', 'adj.', '/ˈmɪstʃɪvəs/', '调皮的;淘气的', 'Twain''s writing is funny and often a little mischievous.', '吐温的文字诙谐,而且常常有点调皮。', 'Laugh Out Loud', 30, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a mischievous smile', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'remark', 'n.', '/rɪˈmɑːk/', '言论;评论;意见', 'He is well known for his witty remarks in everyday life.', '他以日常生活中风趣的言论而广为人知。', 'Laugh Out Loud', 31, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a witty remark', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'interaction', 'n.', '/ˌɪntərˈækʃ(ə)n/', '交流;互动', 'His funny remarks often came out of everyday interaction with people.', '他风趣的话常常来自与人们的日常交流。', 'Laugh Out Loud', 32, 0, 'senior', 'wordlist', 'elective1', 'U1', 'everyday interaction', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'barber', 'n.', '/ˈbɑːbə/', '男理发师', 'Twain once went into a barber''s shop for a haircut.', '吐温有一次走进一家理发店去剪头发。', 'Laugh Out Loud', 33, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a barber''s shop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'shave', 'n.', '/ʃeɪv/', '刮脸;刮胡子', 'He went into the shop for a haircut and a shave.', '他走进店里去剪头发、刮胡子。', 'Laugh Out Loud', 34, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a haircut and a shave', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fellow', 'n.', '/ˈfeləʊ/', '家伙;男人', '''I always have to stand when that fellow lectures,'' he joked.', '''那家伙演讲时我总得站着,''他打趣道。', 'Laugh Out Loud', 35, 0, 'senior', 'wordlist', 'elective1', 'U1', 'that fellow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'brand', 'n.', '/brænd/', '品牌;类型;风格', 'Lin Yutang became famous for his own unique brand of humour.', '林语堂以自己独特风格的幽默而闻名。', 'Laugh Out Loud', 36, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a brand of humour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'concept', 'n.', '/ˈkɒnsept/', '概念;观念', 'He brought the modern concept of humour to Chinese literature.', '他把现代的幽默概念带入了中国文学。', 'Laugh Out Loud', 37, 0, 'senior', 'wordlist', 'elective1', 'U1', 'the concept of humour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spot', 'n.', '/spɒt/', '地点;处所', 'The president put Lin on the spot by suddenly asking for a speech.', '校长突然请林语堂讲话,让他当场为难。', 'Laugh Out Loud', 38, 0, 'senior', 'wordlist', 'elective1', 'U1', 'put sb on the spot', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cruel', 'adj.', '/ˈkruːəl/', '残忍的', 'Lin told a story about a cruel emperor and some wild animals.', '林语堂讲了一个关于残忍皇帝和野兽的故事。', 'Laugh Out Loud', 39, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a cruel emperor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'whisper', 'v.', '/ˈwɪspə/', '悄声说;低语', 'The man bent down to whisper something in the lion''s ear.', '那人弯下腰在狮子耳边悄声说了句话。', 'Laugh Out Loud', 40, 0, 'senior', 'wordlist', 'elective1', 'U1', 'whisper in one''s ear', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'roar', 'v.', '/rɔː/', '哄笑;大笑;吼叫', 'Lin''s audience roared with laughter at his little joke.', '林语堂的听众被他的小笑话逗得哄堂大笑。', 'Laugh Out Loud', 41, 0, 'senior', 'wordlist', 'elective1', 'U1', 'roar with laughter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gently', 'adv.', '/ˈdʒentli/', '温和地;轻柔地', 'With the joke, he gently told off the president.', '他用这个笑话温和地数落了校长一番。', 'Laugh Out Loud', 42, 0, 'senior', 'wordlist', 'elective1', 'U1', 'gently tell off', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'illuminate', 'v.', '/ɪˈluːmɪneɪt/', '照亮;阐明', 'Humour is a tool that can be used to illuminate the world.', '幽默是一种可以用来照亮世界的工具。', 'Laugh Out Loud', 43, 0, 'senior', 'wordlist', 'elective1', 'U1', 'illuminate the world', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'equation', 'n.', '/ɪˈkweɪʒ(ə)n/', '等式;方程式', 'Lin created an equation: Reality plus Dreams plus Humour equals Wisdom.', '林语堂创造了一个等式:现实加梦想加幽默等于智慧。', 'Laugh Out Loud', 44, 0, 'senior', 'wordlist', 'elective1', 'U1', 'create an equation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'complicated', 'adj.', '/ˈkɒmplɪkeɪtɪd/', '难处理的;难懂的;复杂的', 'Working with others can be complicated, but humour makes it easier.', '与人共事可能很复杂,但幽默能让它变得容易些。', 'Laugh Out Loud', 45, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a complicated life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conclude', 'v.', '/kənˈkluːd/', '结束;终止;得出结论', 'A punch line is used to conclude a joke and make people laugh.', '妙语用来给笑话收尾,让人发笑。', 'Laugh Out Loud', 46, 0, 'senior', 'wordlist', 'elective1', 'U1', 'conclude a joke', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'composer', 'n.', '/kəmˈpəʊzə/', '作曲家', 'Charlie Chaplin was a great actor and also a composer.', '查理·卓别林既是伟大的演员,也是一位作曲家。', 'Laugh Out Loud', 47, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a famous composer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fall behind', 'phr.', '/fɔːl bɪˈhaɪnd/', '落后;跟不上', 'When a bee circled his face, Chaplin began to fall behind on the line.', '一只蜜蜂在他脸旁飞来飞去时,卓别林开始跟不上流水线了。', 'Laugh Out Loud', 48, 0, 'senior', 'wordlist', 'elective1', 'U1', 'fall behind with work', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u1.01', '①非限制性 who / which(逗号+补充信息;指人 who、指物 which,that 不可用)', 'A2', 11, '外研社版选择性必修第一册 U1 — 先行词后有逗号、从句提供额外(可省去)信息时,指人用 who、指物 which;非限制性从句绝不用 that;从句缺主语/宾语时不用 where/when。', 1, 'elective1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u1.02', '②非限制性 whose · 介词+which/whom(of which / of whom / in/for + whom)', 'A2', 11, '外研社版选择性必修第一册 U1 — whose+名词表所属;介词后指物用 which、指人用 whom(some of which / many of whom / for whom);介词后不可用 that,也不用 where。', 2, 'elective1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u1.03', '③which 指代整个主句(…, which …,that 不能引导非限制性从句)', 'A2', 11, '外研社版选择性必修第一册 U1 — 逗号后的 which 可指代前面整句话,在从句中作主语/宾语;that/what/it 都不能这样引导非限制性从句。', 3, 'elective1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'My uncle, ____ tells jokes all day, used to work as a circus clown.', 'who', 'which', 'that', 'whom', 'A', '逗号补充信息、先行词 uncle 指人且从句缺主语 → who;非限制性不用 that,whom 需作宾语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The clown doctor, ____ wears a bright red nose, makes sick children laugh.', 'which', 'who', 'that', 'where', 'B', '先行词指人、从句缺主语 → who;where 不能作主语,that 不引导非限制性。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Lara, ____ had hurt her ankle, soon began to smile again.', 'which', 'that', 'who', 'whom', 'C', '先行词为人名、从句缺主语 → who。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The old magazines, ____ had been read hundreds of times, lay on the chairs.', 'who', 'that', 'when', 'which', 'D', '先行词 magazines 指物、从句缺主语 → which;非限制性不用 that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Mark Twain, ____ was an American writer, was famous for his quick wit.', 'who', 'which', 'whose', 'that', 'A', '先行词指人、从句缺主语 → who。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'His curly wig, ____ is bright and colourful, makes the children giggle.', 'who', 'which', 'that', 'where', 'B', '先行词 wig 指物、从句缺主语 → which。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The on-duty nurse, ____ knew Lara well, told the clown her story.', 'which', 'that', 'who', 'whom', 'C', '先行词 nurse 指人、从句缺主语 → who。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Lin Yutang, ____ brought humour to Chinese literature, was a famous writer.', 'which', 'that', 'where', 'who', 'D', '先行词指人、从句缺主语 → who。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The hospital waiting room, ____ felt full of tension, was a rather sad place.', 'which', 'who', 'that', 'whom', 'A', '先行词 room 指物、从句缺主语 → which。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Charlie Chaplin, ____ made silent films, could make people laugh without words.', 'which', 'who', 'that', 'whose', 'B', '先行词指人、从句缺主语 → who。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The funny scene, ____ takes place in a factory, always makes me laugh.', 'who', 'that', 'which', 'where', 'C', '先行词 scene 指物、从句缺主语 → which;where 不能作主语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Doctor Larry, ____ paints a big smile on his face, visits the children every week.', 'which', 'that', 'whom', 'who', 'D', '先行词指人、从句缺主语 → who。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The magic trick, ____ surprised the little girl, made her laugh out loud.', 'which', 'who', 'whom', 'that', 'A', '先行词 trick 指物、从句缺主语 → which;非限制性不用 that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'My grandfather, ____ loves a good joke, often makes the whole family laugh.', 'which', 'who', 'that', 'where', 'B', '先行词指人、从句缺主语 → who。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The silly story, ____ had a clever ending, cheered everyone up.', 'who', 'that', 'which', 'whose', 'C', '先行词 story 指物、从句缺主语 → which。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The two kind doctors, ____ treated Lara''s ankle, also enjoyed the clown''s show.', 'which', 'whom', 'that', 'who', 'D', '先行词 doctors 指人、从句缺主语 → who;whom 需作宾语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Humour, ____ is found in every culture, brings people closer together.', 'which', 'who', 'that', 'where', 'A', '先行词 humour 指物(抽象)、从句缺主语 → which。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The class teacher, ____ rarely laughs at anything, finally cracked a smile.', 'which', 'who', 'that', 'whom', 'B', '先行词 teacher 指人、从句缺主语 → who。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'The big red nose, ____ sits in the middle of his face, is the funniest part.', 'who', 'that', 'which', 'when', 'C', '先行词 nose 指物、从句缺主语 → which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.01'), 'Lin''s quick wit, ____ saved him at the dinner, made everyone admire him.', 'who', 'that', 'whom', 'which', 'D', '先行词 wit 指物、从句缺主语 → which。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The little girl, ____ ankle was badly hurt, would not stop crying.', 'whose', 'who', 'which', 'that', 'A', 'ankle 属于 girl,表所属 → whose。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'Mark Twain, ____ books are still loved today, was a master of wit.', 'which', 'whose', 'who', 'that', 'B', 'books 属于 Twain → whose。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The clown, ____ red nose had fallen off, quickly picked it up again.', 'who', 'that', 'whose', 'which', 'C', 'red nose 属于 clown → whose。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'Lin Yutang, ____ humour was always gentle, made the president laugh.', 'which', 'who', 'whom', 'whose', 'D', 'humour 属于 Lin → whose。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The young patient, ____ smile returned at last, thanked the clown doctor.', 'whose', 'who', 'that', 'which', 'A', 'smile 属于 patient → whose。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'Charlie Chaplin, ____ most famous character is the Tramp, never spoke on screen.', 'which', 'whose', 'that', 'who', 'B', 'character 属于 Chaplin → whose。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The Roman emperor, ____ wild animals all walked away, was completely astonished.', 'who', 'which', 'whose', 'that', 'C', 'animals 属于 emperor → whose。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The comedian, ____ jokes are always clean and kind, is loved by children.', 'whom', 'who', 'which', 'whose', 'D', 'jokes 属于 comedian → whose。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'My best friend, ____ sense of humour is wonderful, can always make me laugh.', 'whose', 'who', 'that', 'which', 'A', 'sense of humour 属于 friend → whose。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The busy hospital, ____ staff work very hard, warmly welcomes the clown doctors.', 'which', 'whose', 'who', 'where', 'B', 'staff 属于 hospital → whose。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'He looked through the old magazines, all of ____ had been read many times before.', 'whom', 'who', 'which', 'that', 'C', '介词 of 后指物 → of which;magazines 是物。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The clown doctors, many of ____ once trained as actors, also learn medical skills.', 'which', 'who', 'that', 'whom', 'D', '介词 of 后指人 → of whom;clown doctors 是人。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'On a typical day they meet many patients, some of ____ are very young.', 'whom', 'which', 'that', 'who', 'A', '介词 of 后指人 → some of whom。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'He tried several jokes, none of ____ made the frightened boy laugh.', 'whom', 'which', 'who', 'that', 'B', '介词 of 后指物 → none of which;jokes 是物。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The doctor used a special medicine, the effect of ____ surprised everyone.', 'whom', 'who', 'which', 'that', 'C', '介词 of 后指物 → the effect of which。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'Lin met two professors, both of ____ enjoyed his witty little story.', 'which', 'that', 'who', 'whom', 'D', '介词 of 后指人 → both of whom。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The large audience, in front of ____ Lin stood, waited for his speech.', 'whom', 'which', 'who', 'that', 'A', '介词 in front of 后指人 → whom。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'She told a long story, the ending of ____ made the whole class roar.', 'whom', 'which', 'who', 'that', 'B', '介词 of 后指物 → the ending of which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'The kind nurses keep us updated, for ____ we are all very grateful.', 'which', 'that', 'whom', 'who', 'C', '介词 for 后指人 → for whom。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.02'), 'He kept several red noses, one of ____ was far bigger than the others.', 'whom', 'who', 'that', 'which', 'D', '介词 of 后指物 → one of which;noses 是物。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Laughter produces helpful chemicals, ____ means clown doctors can really help.', 'which', 'that', 'what', 'it', 'A', '逗号后指代前面整句话、作从句主语 → which;that/what/it 都不能引导非限制性从句。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'He produced her sock from his pocket, ____ made the little girl laugh.', 'what', 'which', 'that', 'it', 'B', 'which 指代整件事、作主语;that 不引导非限制性从句。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'The clown sang and danced, ____ cheered up the whole ward.', 'that', 'this', 'which', 'what', 'C', 'which 指代前面整句;this/that 都不能引导从句。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Twain replied with a witty remark, ____ completely surprised the barber.', 'what', 'that', 'it', 'which', 'D', 'which 指代整句、作主语;非限制性不用 that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Lin told a short joke, ____ made his whole audience roar with laughter.', 'which', 'that', 'so', 'what', 'A', 'which 指代整句、作主语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'The doctors did a great job, ____ made Lara''s parents feel relieved.', 'what', 'which', 'that', 'it', 'B', 'which 指代整句、作主语;it 会造成无连词的并列句。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'The children kept laughing, ____ showed the magic medicine had worked.', 'that', 'what', 'which', 'this', 'C', 'which 指代整句、作主语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'He forgot all his lines on stage, ____ made the whole class laugh.', 'what', 'that', 'it', 'which', 'D', 'which 指代整句、作主语;that 不引导非限制性从句。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Chaplin never spoke in his films, ____ made his clever acting even funnier.', 'which', 'that', 'what', 'so', 'A', 'which 指代整句、作主语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'She finally cracked a smile, ____ pleased her tired and worried parents.', 'what', 'which', 'that', 'it', 'B', 'which 指代整件事、作主语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Their tent had been stolen, ____ Holmes had completely failed to notice.', 'that', 'what', 'which', 'this', 'C', 'which 指代整句、作 notice 的宾语;that/what 不引导非限制性从句。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Humour brings people together, ____ is one reason we need it so much.', 'what', 'that', 'it', 'which', 'D', 'which 指代整句、作主语。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'The clown pretended to trip over a chair, ____ made the children giggle.', 'which', 'that', 'what', 'so', 'A', 'which 指代整件事、作主语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Twain often made witty remarks, ____ won him fame far beyond America.', 'what', 'which', 'that', 'it', 'B', 'which 指代整句、作主语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'The nurse kept us updated, ____ helped us care for each patient better.', 'that', 'what', 'which', 'this', 'C', 'which 指代整件事、作主语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'He put on his wig and red nose, ____ instantly changed him into a clown.', 'what', 'that', 'it', 'which', 'D', 'which 指代整件事、作主语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Lara stopped crying at last, ____ was exactly what the clown had hoped for.', 'which', 'that', 'what', 'so', 'A', 'which 指代整件事、作主语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'The whole audience laughed loudly, ____ greatly encouraged the young comedian.', 'what', 'which', 'that', 'it', 'B', 'which 指代整句、作主语。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Lin gently told off the president, ____ nobody had expected him to do.', 'that', 'what', 'which', 'this', 'C', 'which 指代前面的行为、作 do 的宾语;that/what 不引导非限制性从句。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U1' AND code='fe1u1.03'), 'Good humour can lighten hard times, ____ is why people value it so highly.', 'what', 'that', 'it', 'which', 'D', 'which 指代整句、作主语。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Day as a Clown Doctor', 'As I walk into the hospital in my white coat, I look like any ordinary doctor. Then I put on my curly rainbow wig, my big red nose and a name badge that reads ''Doctor Laugh-Out-Loud''. I am a clown doctor. I work as part of a programme called hospital clowning. On a typical day, my job is to cheer up young patients, their families and even the tired hospital staff. We do this by doing magic tricks, singing songs, telling stories and, of course, telling silly jokes. We must be very sensitive, because some children are in too much pain to laugh. So we work closely with the doctors and nurses, who keep us updated on each patient. I chose this career because of my own childhood visits to hospital, where I often felt frightened and bored. Being a clown doctor means I can help people simply by making them smile.', '记叙·小丑医生的一天', 152, '[{"q":"What does the writer add in order to become a clown doctor?","answer":"A","options":["Some colourful clothes and a funny false nose.","Only a plain white doctor''s coat.","A camera and a thick notebook.","A nurse''s blue uniform."],"explanation":"原文 ''curly rainbow wig, my big red nose and a name badge'' 的转述。"},{"q":"Who does the clown doctor try to cheer up on a typical day?","answer":"B","options":["Only the senior doctors.","Sick children, their families and the staff.","Just the visitors at the front door.","Only very old patients."],"explanation":"原文 ''cheer up young patients, their families and even the tired hospital staff'' 的转述。"},{"q":"Why did the writer choose this job?","answer":"A","options":["Because hospitals had felt scary to them as a child.","Because clowns earn a great deal of money.","Because they once failed to become a nurse.","Because they did not like working with children."],"explanation":"末段 ''因为童年住院时常感到害怕和无聊'' 的转述。"}]'::jsonb, '[{"word":"wig","cn":"假发"},{"word":"badge","cn":"徽章;名牌"},{"word":"sensitive","cn":"敏感的;善解人意的"}]'::jsonb, 2, 'elective1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Mark Twain''s Quick Wit', 'Mark Twain was an American writer who is still remembered for mixing humour with serious ideas. His style of writing was funny and often a little naughty. He once joked that writing was easy: all you had to do was cross out the wrong words. But Twain was just as well known for his quick replies in everyday life. One day, while travelling around the country giving talks, he went into a barber''s shop for a haircut and a shave. The barber did not recognise him and asked whether he had a ticket for the evening lecture. When Twain said he did not, the barber warned him that he would have to stand, because every single seat had already been sold. ''That''s just my luck,'' Twain replied at once. ''I always have to stand when that fellow lectures!'' People loved him for this kind of wit, and his fame soon spread far beyond America.', '记叙·马克·吐温的机智', 154, '[{"q":"What was special about Mark Twain''s writing?","answer":"B","options":["It was always sad and very serious.","It mixed jokes with serious messages.","It contained no humour at all.","It was written only for small children."],"explanation":"原文 ''mixing humour with serious ideas'' 的转述。"},{"q":"Why did Twain go into the barber''s shop?","answer":"C","options":["To buy a ticket for the lecture.","To give a free evening talk.","To get his hair cut and have a shave.","To look for an empty seat."],"explanation":"原文 ''for a haircut and a shave'' 的转述。"},{"q":"What did Twain mean by his reply about having to stand?","answer":"D","options":["He really wanted the barber to work faster.","He was angry that the seats had all gone.","He honestly had no ticket left to sell.","He jokingly pretended that even he found his own talks dull."],"explanation":"他正是那位演讲者,却假装连自己都不爱听,以此自嘲取乐。"}]'::jsonb, '[{"word":"barber","cn":"男理发师"},{"word":"wit","cn":"机智;风趣"},{"word":"fame","cn":"名声"}]'::jsonb, 2, 'elective1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Lin Yutang and the Word ''Youmo''', 'On the other side of the world, the Chinese writer Lin Yutang became famous for his own special brand of humour. A well-known writer in both Chinese and English, Lin first brought the modern idea of humour to Chinese literature. In 1924 he cleverly borrowed the old word ''youmo'' to stand for the English word ''humour'', and people still use it in this way today. Lin''s quick wit once saved him at a dinner. The university president suddenly asked him to give a speech, putting him on the spot. Thinking fast, Lin told a story about a cruel emperor who tried to feed a man to wild animals. The man whispered something into each animal''s ear, and one by one the beasts hurried away in fear. ''What on earth did you say to them?'' asked the emperor. ''I told them they must each give a speech after their meal,'' Lin answered. The guests roared with laughter, and the president quietly understood the gentle joke.', '记叙·林语堂与''幽默''', 164, '[{"q":"What did Lin Yutang do in 1924?","answer":"A","options":["He used an old Chinese word to stand for ''humour''.","He invented a brand-new spoken language.","He stopped writing in English for good.","He left China and never came back."],"explanation":"原文 ''borrowed the old word youmo to stand for humour'' 的转述。"},{"q":"Why did Lin tell the story about the emperor?","answer":"B","options":["He wanted to frighten all the dinner guests.","He had been suddenly asked to make a speech.","He was giving a serious history lesson.","He really disliked wild animals."],"explanation":"原文 ''校长突然请他讲话,让他当场为难'' 的转述。"},{"q":"How did the guests react to Lin''s little joke?","answer":"C","options":["They felt bored and quietly left.","They became angry with Lin.","They burst out laughing.","They did not understand a single word."],"explanation":"原文 ''roared with laughter'' 的转述。"}]'::jsonb, '[{"word":"brand","cn":"风格;类型"},{"word":"whisper","cn":"悄声说"},{"word":"roar","cn":"哄笑"}]'::jsonb, 2, 'elective1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Tricks on April Fool''s Day', 'April Fool''s Day falls on the first of April. It is the one day of the year when people in many countries play tricks on one another just for fun. Even newspapers, radio stations and television channels join in by fooling their readers and audiences. In Britain, the jokes traditionally have to stop at noon, but in some places, such as the United States, they can carry on all day long. Some of the most famous tricks are remembered for years. In 1957, a British television programme told viewers that spaghetti grew on trees, and even showed a family happily picking it. Surprisingly, many people actually believed it. On another April Fool''s Day, a radio show announced a clever new machine that could send smells through the air into people''s homes. These tricks are not meant to be cruel. They simply remind us that laughter and a sense of fun can be shared by a whole country at the very same time.', '说明·愚人节的恶作剧', 162, '[{"q":"When must the April Fool jokes traditionally stop in Britain?","answer":"D","options":["At midnight.","Early in the morning.","They are never allowed to stop.","By the middle of the day."],"explanation":"原文 ''stop at noon'' 的转述。"},{"q":"What did the famous 1957 television trick claim?","answer":"A","options":["That spaghetti could grow on trees.","That smells could be sent through the post.","That noon had been cancelled that year.","That all the newspapers were closed."],"explanation":"原文 ''spaghetti grew on trees'' 的转述。"},{"q":"What does the writer say about these tricks?","answer":"B","options":["They are designed to hurt and upset people.","They are light-hearted rather than unkind.","They are meant only for very small children.","They have now been banned everywhere."],"explanation":"原文 ''not meant to be cruel'' 的转述。"}]'::jsonb, '[{"word":"fool","cn":"愚弄"},{"word":"audience","cn":"观众;听众"}]'::jsonb, 2, 'elective1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Charlie Chaplin and the Tramp', 'Charlie Chaplin was a British actor, film-maker and composer. He became famous in the 1910s, at a time when films were silent and in black and white. Many people think he was one of the greatest comedy actors ever, because he knew exactly how to use his body and his face to make audiences laugh. His most famous character was the Tramp, a poor little man with a kind heart who keeps having unexpected adventures. These adventures, which often involve the police, give us some of the funniest scenes in film history. In one favourite film, Modern Times, the Tramp works on a fast production line in a factory. When a bee starts flying around his face, he falls behind with his work, and it is wonderful to watch him trying to keep up. Even today, long after the films were made, the little Tramp still makes brand-new audiences laugh. That, perhaps, is the real power of Chaplin''s work.', '说明·卓别林与流浪汉形象', 159, '[{"q":"Why do many people admire Charlie Chaplin?","answer":"C","options":["He spoke beautifully in all of his films.","He wrote long and serious novels.","He used his body and face cleverly to make people laugh.","He never once made a single mistake."],"explanation":"原文 ''how to use his body and his face to make audiences laugh'' 的转述。"},{"q":"Who was the Tramp?","answer":"D","options":["A rich and famous police officer.","A clever factory owner.","A serious news reader.","A poor but kind-hearted little man."],"explanation":"原文 ''a poor little man with a kind heart'' 的转述。"},{"q":"What happens in the factory scene of Modern Times?","answer":"A","options":["A bee distracts him so that he cannot keep up.","He becomes the new manager of the factory.","He quietly repairs a broken machine.","He leaves the difficult job at once."],"explanation":"原文 ''a bee... he falls behind with his work'' 的转述。"}]'::jsonb, '[{"word":"composer","cn":"作曲家"},{"word":"silent","cn":"无声的"}]'::jsonb, 2, 'elective1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Is Laughter the Best Medicine?', 'People have said for a long time that ''laughter is the best medicine'', and scientists now believe there is some truth in it. Studies show that laughing causes the body to produce helpful chemicals, which can make us feel happier and less worried. This is one reason why clown doctors are welcomed in so many hospitals. When a child laughs, the pain often seems smaller, and the worried parents slowly begin to relax as well. Laughter is good for the mind too. Sharing a joke can bring complete strangers together and turn a tense room into a friendly one. Some people even say that our need for humour is almost as great as our need for water and air. Of course, a single joke cannot cure a broken bone or heal an illness on its own. But a warm smile and a good laugh can make any difficult day feel a little easier, and that is something everyone is able to share.', '议论·笑是最好的良药', 162, '[{"q":"What do scientific studies show about laughing?","answer":"B","options":["It has no effect at all on the body.","It makes the body release helpful chemicals.","It makes people feel far more worried.","It can cure every illness completely."],"explanation":"原文 ''laughing causes the body to produce helpful chemicals'' 的转述。"},{"q":"How do the parents react when a child laughs?","answer":"C","options":["They become much more frightened.","They leave the hospital straight away.","They begin to feel calmer.","They suddenly start to cry."],"explanation":"原文 ''worried parents slowly begin to relax'' 的转述。"},{"q":"What does the writer admit about jokes?","answer":"D","options":["They are always better than any real doctor.","They are useless and a complete waste of time.","They can fully replace water and air.","They cannot heal serious injuries by themselves."],"explanation":"原文 ''a single joke cannot cure a broken bone or heal an illness on its own'' 的转述。"}]'::jsonb, '[{"word":"chemical","cn":"化学物质"},{"word":"tense","cn":"紧张的"}]'::jsonb, 2, 'elective1', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'Applying to Be a Clown Doctor', 'Dear Sir or Madam, I saw your (1)____ for a part-time clown doctor and I would love to (2)____. Ever since I was a child, I have wanted to (3)____ sick people feel better. I am cheerful, patient and good at telling (4)____. I can also do simple magic (5)____, sing funny songs and make balloon animals. I understand that a clown doctor must be very (6)____, because some children are in too much pain to laugh. I would always work (7)____ with the doctors and nurses on the ward. Making a frightened child (8)____ again would be the best reward of all. I have included my CV and two (9)____ from my teachers. I really hope you will give me the (10)____ to join your wonderful team.', 128, 2, '[{"q":"1","answer":"A","options":["advertisement","weather","machine","ankle"],"explanation":"saw your advertisement 看到广告。"},{"q":"2","answer":"B","options":["sleep","apply","refuse","forget"],"explanation":"love to apply 乐意应聘。"},{"q":"3","answer":"C","options":["sell","lose","help","drop"],"explanation":"help sick people feel better 帮病人好起来。"},{"q":"4","answer":"D","options":["prices","mistakes","machines","jokes"],"explanation":"telling jokes 讲笑话。"},{"q":"5","answer":"A","options":["tricks","noises","debts","roots"],"explanation":"magic tricks 魔术。"},{"q":"6","answer":"B","options":["angry","sensitive","lazy","careless"],"explanation":"must be sensitive 必须善解人意。"},{"q":"7","answer":"C","options":["rarely","hardly","closely","badly"],"explanation":"work closely with 密切合作。"},{"q":"8","answer":"D","options":["shout","fall","hide","smile"],"explanation":"make a child smile 让孩子笑。"},{"q":"9","answer":"A","options":["letters","songs","tricks","noses"],"explanation":"two letters from my teachers 两封推荐信。"},{"q":"10","answer":"B","options":["problem","chance","mistake","noise"],"explanation":"give me the chance 给我机会。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'The Story of the Circus', 'Long before films and television, the (1)____ was one of the most exciting forms of entertainment. Families would travel for miles to (2)____ the show. Under the big tent, acrobats flew through the air, while trained animals (3)____ amazing tricks. But for many children, the (4)____ were the real stars. With their colourful wigs, painted faces and big red (5)____, they made the whole crowd (6)____ with laughter. A really good clown did not need to (7)____ a single word; a silly walk or a sudden fall was (8)____ to make everyone giggle. Some performers spent years learning how to (9)____ their audience. Even today, when we think of the circus, the first picture that comes to (10)____ is often a smiling clown.', 123, 2, '[{"q":"1","answer":"C","options":["library","factory","circus","hospital"],"explanation":"the circus 马戏团。"},{"q":"2","answer":"D","options":["sell","forget","repair","watch"],"explanation":"watch the show 看演出。"},{"q":"3","answer":"A","options":["performed","sold","lost","dropped"],"explanation":"performed tricks 表演把戏。"},{"q":"4","answer":"B","options":["doctors","clowns","farmers","drivers"],"explanation":"the clowns were the real stars 小丑才是明星。"},{"q":"5","answer":"C","options":["books","wheels","noses","coins"],"explanation":"big red noses 大红鼻子。"},{"q":"6","answer":"D","options":["sleep","cry","leave","roar"],"explanation":"roar with laughter 哄堂大笑。"},{"q":"7","answer":"A","options":["say","buy","throw","hide"],"explanation":"say a single word 说一个字。"},{"q":"8","answer":"B","options":["late","enough","empty","sorry"],"explanation":"was enough 就足够了。"},{"q":"9","answer":"C","options":["frighten","ignore","entertain","lose"],"explanation":"entertain their audience 取悦观众。"},{"q":"10","answer":"D","options":["market","garden","machine","mind"],"explanation":"comes to mind 浮现脑海。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'How to Tell a Good Joke', 'Telling a joke well is a real (1)____. First, you need to choose a story that your listeners will (2)____. A joke that is too (3)____ may only confuse them, while one they have heard before will simply (4)____ them. Next, take your time. Good comedians never (5)____; they let the story build up slowly. The most important part is the punch (6)____ at the very end, which should come as a surprise. If you say it too early, you will (7)____ the whole joke. It also helps to keep a straight face, because laughing at your own joke can (8)____ the ending. Remember that even the funniest words will fall flat if your (9)____ is wrong. With a little practice, however, anyone can learn to make a room full of people (10)____.', 133, 2, '[{"q":"1","answer":"A","options":["skill","price","noise","debt"],"explanation":"a real skill 一门真本事。"},{"q":"2","answer":"B","options":["sell","understand","lose","break"],"explanation":"listeners will understand 听众能懂。"},{"q":"3","answer":"C","options":["cheap","quiet","complicated","empty"],"explanation":"too complicated 太复杂。"},{"q":"4","answer":"D","options":["help","save","please","bore"],"explanation":"will bore them 让人厌倦。"},{"q":"5","answer":"A","options":["rush","sleep","sing","pay"],"explanation":"never rush 从不着急。"},{"q":"6","answer":"B","options":["weather","line","market","price"],"explanation":"punch line 妙语;包袱。"},{"q":"7","answer":"C","options":["improve","win","ruin","enjoy"],"explanation":"ruin the joke 毁掉笑话。"},{"q":"8","answer":"D","options":["save","repair","build","spoil"],"explanation":"spoil the ending 破坏结尾。"},{"q":"9","answer":"A","options":["timing","weather","price","machine"],"explanation":"if your timing is wrong 时机不对。"},{"q":"10","answer":"B","options":["cry","laugh","sleep","leave"],"explanation":"make people laugh 逗人笑。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'A Funny Family Dinner', 'Last Sunday my whole family came together for (1)____. Everything was going well until my little brother told a (2)____ that he had heard at school. It was so silly that nobody could (3)____ a smile at first. Then Grandpa, who rarely (4)____ at anything, suddenly burst out laughing. His laugh was so loud that it made the rest of us (5)____ too. Soon the whole table was (6)____ with laughter, and Mum almost dropped the soup. My brother looked very (7)____ of himself. He said it felt wonderful to make everyone so (8)____. After dinner we kept telling silly stories, each one funnier than the (9)____. It was a simple evening, but it reminded me that a good laugh is one of the best ways to bring a family (10)____.', 131, 2, '[{"q":"1","answer":"C","options":["school","market","dinner","factory"],"explanation":"together for dinner 共进晚餐。"},{"q":"2","answer":"D","options":["price","machine","root","joke"],"explanation":"told a joke 讲了个笑话。"},{"q":"3","answer":"A","options":["crack","sell","lose","throw"],"explanation":"crack a smile 露出笑容。"},{"q":"4","answer":"B","options":["slept","laughed","paid","drove"],"explanation":"rarely laughed 很少笑。"},{"q":"5","answer":"C","options":["cry","leave","grin","sleep"],"explanation":"made us grin 让我们咧嘴笑。"},{"q":"6","answer":"D","options":["sleeping","crying","paying","roaring"],"explanation":"roaring with laughter 哄堂大笑。"},{"q":"7","answer":"A","options":["proud","afraid","angry","bored"],"explanation":"proud of himself 为自己自豪。"},{"q":"8","answer":"B","options":["sad","happy","tired","quiet"],"explanation":"make everyone happy 让大家开心。"},{"q":"9","answer":"C","options":["price","noise","last","weather"],"explanation":"funnier than the last 一个比一个好笑。"},{"q":"10","answer":"D","options":["apart","behind","away","together"],"explanation":"bring a family together 让家人更亲近。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'Joining the Comedy Club', 'When I first joined the school (1)____ club, I was terribly nervous. I had always wanted to make people (2)____, but standing alone on a stage felt frightening. My teacher told me not to (3)____ up after my first try went badly. She said that every comedian (4)____ a few jokes that nobody laughs at. So I kept (5)____. I learned to speak slowly, to look at the audience, and to wait for the right (6)____ to deliver my best line. Little by little, my acts became (7)____, and people really started to laugh. At our last show, the whole hall (8)____ with laughter at my final joke. I felt so (9)____ as I walked off the stage. Now I know that, with patience and practice, anyone can learn to be truly (10)____.', 133, 2, '[{"q":"1","answer":"A","options":["comedy","weather","market","machine"],"explanation":"the comedy club 喜剧社。"},{"q":"2","answer":"B","options":["cry","laugh","sleep","leave"],"explanation":"make people laugh 逗人笑。"},{"q":"3","answer":"C","options":["sell","throw","give","lose"],"explanation":"give up 放弃。"},{"q":"4","answer":"D","options":["sells","breaks","hides","tells"],"explanation":"every comedian tells 每个笑星都会讲。"},{"q":"5","answer":"A","options":["practising","sleeping","paying","leaving"],"explanation":"kept practising 坚持练习。"},{"q":"6","answer":"B","options":["price","moment","noise","debt"],"explanation":"the right moment 合适的时机。"},{"q":"7","answer":"C","options":["quieter","shorter","funnier","sadder"],"explanation":"became funnier 越来越好笑。"},{"q":"8","answer":"D","options":["slept","cried","paid","roared"],"explanation":"the hall roared 全场哄笑。"},{"q":"9","answer":"A","options":["proud","afraid","bored","angry"],"explanation":"felt so proud 非常自豪。"},{"q":"10","answer":"B","options":["silent","funny","lazy","rude"],"explanation":"learn to be funny 学会幽默。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'My Grandfather''s Sense of Humour', 'My grandfather has the best sense of (1)____ of anyone I know. Even when life is (2)____, he always finds something to laugh about. He says that a good joke can (3)____ up even the darkest day. When I was small and felt sad, he would (4)____ a silly story to cheer me up. His jokes were never (5)____; they were always kind and gentle. People who meet him for the first time are quickly (6)____ by his warm laugh. He firmly believes that sharing humour helps to bring people (7)____. ''Laughter,'' he often (8)____, ''is something everyone can share, like water and air.'' Thanks to him, I have learned to look for the (9)____ side of things. Whenever I feel down, I remember his words and try to (10)____ a smile.', 132, 2, '[{"q":"1","answer":"C","options":["weather","price","humour","market"],"explanation":"sense of humour 幽默感。"},{"q":"2","answer":"D","options":["easy","quiet","empty","hard"],"explanation":"life is hard 生活艰难。"},{"q":"3","answer":"A","options":["light","sell","lose","break"],"explanation":"light up the day 照亮一天。"},{"q":"4","answer":"B","options":["sell","tell","throw","hide"],"explanation":"tell a silly story 讲个傻故事。"},{"q":"5","answer":"C","options":["kind","funny","cruel","gentle"],"explanation":"never cruel 从不刻薄(后文说总是友善)。"},{"q":"6","answer":"D","options":["frightened","bored","ignored","impressed"],"explanation":"impressed by his laugh 被他的笑声打动。"},{"q":"7","answer":"A","options":["together","apart","behind","down"],"explanation":"bring people together 拉近人们。"},{"q":"8","answer":"B","options":["sells","says","eats","drives"],"explanation":"he often says 他常说。"},{"q":"9","answer":"C","options":["dark","heavy","bright","empty"],"explanation":"the bright side 光明的一面。"},{"q":"10","answer":"D","options":["sell","throw","drop","crack"],"explanation":"crack a smile 露出笑容。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Choosing a Funny Film', '外研社版选择性必修第一册 U1 · dialogue', 3, 'Anna: Have you seen any good comedies lately?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 What Clown Doctors Do', '外研社版选择性必修第一册 U1 · passage', 2, 'Clown doctors are specially trained performers who work in hospitals.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 An April Fool''s Trick', '外研社版选择性必修第一册 U1 · dialogue', 3, 'Cara: Did anyone trick you on April Fool''s Day?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 Mark Twain at the Barber''s', '外研社版选择性必修第一册 U1 · passage', 2, 'Mark Twain was famous for his quick wit.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Planning a Comedy Act', '外研社版选择性必修第一册 U1 · dialogue', 3, 'Eva: We need to plan our comedy act for the school show. Any ideas?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 A Tip for a Happier Life', '外研社版选择性必修第一册 U1 · passage', 2, 'Here is a simple tip for a happier life: try to laugh every day.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write an Introduction to a Comedian(写一篇喜剧演员介绍)', 'A Comedian Who Makes Me Laugh', '请用英语写一篇约 80 词的短文,向同学介绍一位让你发笑的喜剧演员,内容包括:① 简要介绍他/她是谁;② 你为什么喜欢他/她;③ 他/她最好笑的一部作品或一个片段;④ 你的评价。注意尽量用上非限制性定语从句(如 …, who … / …, which …)。', 'Write a short text (about 80 words) introducing a comedian who makes you laugh. Include: 1) a brief introduction to who they are; 2) why you like them; 3) their funniest work or scene; 4) your own comment. Try to use non-defining relative clauses (e.g. …, who … / …, which …).', '["介绍是谁(… is a comedian / actor who …)","为什么喜欢(I like him/her because …)","最好笑的作品或片段(His funniest scene is …, which …)","你的评价 + 尽量用非限制性定语从句"]'::jsonb, 70, 100, 'My favourite comedian is Charlie Chaplin, who became famous when films were still silent. I love him because he could make people laugh without saying a single word. His most famous character is the Tramp, who is a poor but kind-hearted little man. In my favourite film, Modern Times, the Tramp falls behind on a factory line, which always makes me roar with laughter. Chaplin showed that humour, which needs no language, can bring joy to people all over the world.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["My favourite comedian is Charlie Chaplin, who became famous when films were still silent.","His most famous character is the Tramp, who is a poor but kind-hearted little man.","The Tramp falls behind on a factory line, which always makes me roar with laughter.","Chaplin showed that humour, which needs no language, can bring joy to people everywhere."]'::jsonb, '[{"wrong":"Charlie Chaplin, that became famous, made silent films.","correct":"Charlie Chaplin, who became famous, made silent films.","note":"非限制性定语从句指人用 who,绝不用 that。"},{"wrong":"He fell into a cake, that made everyone laugh.","correct":"He fell into a cake, which made everyone laugh.","note":"逗号后指代整句话用 which,不用 that。"},{"wrong":"The Tramp, who his heart is kind, helps others.","correct":"The Tramp, whose heart is kind, helps others.","note":"表所属(他的心)用 whose,不用 who。"}]'::jsonb, '【喜剧演员介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U1', '{"title":"非限制性定语从句·which / who / whose / 介词+which 速查","intro":"非限制性定语从句给先行词补充''额外的、可省去的''信息,前面一定有逗号。指人用 who、指物用 which、表所属用 whose;逗号后的 which 还能指代前面一整句话。关键铁律:非限制性从句绝不能用 that。","table":{"headers":["关系词","用法 / 例句"],"rows":[["who","指人作主语/宾语:Mark Twain, who was a writer, loved jokes."],["which","指物:His wig, which is bright, makes children laugh."],["whose","表所属(……的):The girl, whose ankle hurt, cried."],["介词+which/whom","some of which / many of whom / for whom:jokes, none of which were funny"],["which 指整句","He told a joke, which made everyone laugh.(which=前面整件事)"]]},"specialRules":[{"rule":"非限制性定语从句前必有逗号,且绝不能用 that","mark":"…, who/which … √  …, that … ×"},{"rule":"指人 who / 指物 which;表所属一律 whose(指人指物都行)","mark":"the clown, whose nose fell off"},{"rule":"介词后指物用 which、指人用 whom,不能用 that 或 where","mark":"some of whom / one of which"},{"rule":"逗号后的 which 可指代前面一整句话,在从句中作主语或宾语","mark":"…, which means clown doctors can help."}],"why":["限制性从句是''缺它不可''的身份信息,不加逗号;非限制性从句只是''顺便补充'',去掉后主句意思仍完整,所以用逗号隔开,而 that 语气太''紧'',不能用来引导这种松散的补充说明。"],"gaokaoPoints":["逗号 + 空格几乎=不能填 that:指人 who、指物 which、表所属 whose 三选一。","''…, which + 谓语''指代整个主句,是写作高分句型(which means / which makes / which is why)。","介词+关系词:数量词 of which / of whom(some / many / none / both / one of …)是高频考点。"],"examVsReal":[{"exam":"The film, which is very funny, won a prize.(考试/书面)","real":"The film''s really funny — it won a prize.","note":"口语常拆成两句、用破折号,而书面用非限制性从句更紧凑。"},{"exam":"…, some of whom trained as actors（考试)","real":"…, and some of them trained as actors","note":"口语爱用''and + 代词'',考试更看重''介词+whom/which''的规范形式。"}]}'::jsonb, 'fltrp');
